def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits = ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_group(num):
        """Read a group of up to 4 digits (0-9999)"""
        if num == 0:
            return ''

        result = ''

        # 천 (thousands)
        thousands = num // 1000
        if thousands > 0:
            if thousands != 1:
                result += digits[thousands]
            result += '천'

        # 백 (hundreds)
        hundreds = (num % 1000) // 100
        if hundreds > 0:
            if hundreds != 1:
                result += digits[hundreds]
            result += '백'

        # 십 (tens)
        tens = (num % 100) // 10
        if tens > 0:
            if tens != 1:
                result += digits[tens]
            result += '십'

        # 일 (ones)
        ones = num % 10
        if ones > 0:
            result += digits[ones]

        return result

    # Break number into groups: ones (0-9999), 만 (10000-99999999), 억 (100000000+)
    ones_group = n % 10000
    mans_group = (n % 100000000) // 10000
    eoks_group = n // 100000000

    result = ''

    # 억 group (always include the number if non-zero)
    if eoks_group > 0:
        result += read_group(eoks_group) + '억'

    # 만 group (special: if exactly 1, read as just 만)
    if mans_group > 0:
        if mans_group == 1:
            result += '만'
        else:
            result += read_group(mans_group) + '만'

    # ones group (always read if non-zero)
    if ones_group > 0:
        result += read_group(ones_group)

    return result
